#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Only non-secret selections are remembered. Never source this file as shell code.
set -E
die() { printf '\nStopped: %s\n' "$*" >&2; exit 1; }
need() { command -v "$1" >/dev/null 2>&1 || die "Required command missing: $1"; }
valid_release() { [[ "$1" =~ ^release-[0-9]{8}-[0-9]{2,}$ ]]; }
failed() {
  printf '\nOperation failed (exit %s). No automatic rollback or reactivation was attempted.\n' "$1" >&2
  printf 'Keep affected access fenced. Inspect the service and the recorded rollback directory.\n' >&2
}
select_release() {
  ask EPM_RELEASE "Release ID (release-YYYYMMDD-NN):"
  valid_release "$EPM_RELEASE" || die "Invalid release identifier."
  next="/opt/epm/releases/$EPM_RELEASE"
  write_env EPM_RELEASE "$EPM_RELEASE"
}
select_instance() {
  ask EPM_INSTANCE "Instance (a or b):"
  [[ "$EPM_INSTANCE" == a || "$EPM_INSTANCE" == b ]] || die "Choose a or b."
  instance="$EPM_INSTANCE"
  port=8001
  [[ "$instance" != b ]] || port=8002
  unit="epm-hosted@$instance.service"
  account="epm-$instance"
  local_config="/var/lib/$account/hosted-local.json"
  deployment="/etc/epm/hosted-$instance.json"
  dropin="/etc/systemd/system/$unit.d/90-release.conf"
  write_env EPM_INSTANCE "$instance"
}
# Parse only a fixed installed interpreter path; never evaluate systemd output.
runtime_from_exec() {
  local value="$1" regex='path=(/opt/epm/releases/[A-Za-z0-9][A-Za-z0-9._-]*/venv/bin/python)[ ;}]'
  [[ "$value" =~ $regex ]] || die "Cannot identify the installed interpreter in effective ExecStart."
  printf '%s\n' "${BASH_REMATCH[1]}"
}
check_exec() {
  local value="$1" expected_python="$2"
  [[ "$(runtime_from_exec "$value")" == "$expected_python" ]] || die "Effective interpreter differs from selected release."
  [[ "$value" == *"--config $local_config "* && "$value" == *"--deployment $deployment "* ]] ||
    die "Effective ExecStart points to another instance's configuration."
  local regex="--port[[:space:]]+$port([[:space:];}]|$)"
  [[ "$value" =~ $regex ]] || die "Effective ExecStart has the wrong port."
}
current_python() {
  local command
  command="$(sudo systemctl show "$unit" -p ExecStart --value)"
  previous_python="$(runtime_from_exec "$command")"
  check_exec "$command" "$previous_python"
  cli_check "$previous_python"
  say "Effective current interpreter: $previous_python"
}
as_owner() {
  local python="$1"; shift
  sudo -u "$account" env -u PYTHONPATH -u PYTHONHOME \
    TMPDIR="/var/lib/$account/volume/tmp" "$python" -m app --config "$local_config" "$@"
}
cli_check() {
  local help
  help="$(as_owner "$1" --help)"
  [[ "$help" == *hosted-backup* && "$help" == *hosted-admin* && "$help" == *validate-hosted-config* ]] ||
    die "This is not the hosted CLI. Do not use demo-001 or local backup as a substitute."
}
validate_instance() {
  as_owner "$1" workspace-status
  as_owner "$1" validate-hosted-config "$deployment"
}
ensure_stopped() {
  local state pid
  state="$(sudo systemctl show "$unit" -p ActiveState --value)"
  pid="$(sudo systemctl show "$unit" -p MainPID --value)"
  [[ "$pid" == 0 && ( "$state" == inactive || "$state" == failed ) ]] ||
    die "$unit is not stopped (state=$state, PID=$pid)."
  sudo systemctl reset-failed "$unit"
}
read_origin() {
  origin="$(sudo "$next/venv/bin/python" -c \
    'import json,sys; print(json.load(open(sys.argv[1]))["public_origin"])' "$deployment")"
  [[ "$origin" =~ ^https://[a-z0-9][a-z0-9.-]+$ ]] || die "Invalid protected public origin."
  host="${origin#https://}"
}
readiness() {
  local count sign_in_code api_code pid restarts
  for count in {1..30}; do
    if sudo systemctl is-active --quiet "$unit"; then
      sign_in_code="$(curl --max-time 3 -s -o /dev/null -w '%{http_code}' \
        -H "Host: $host" -H 'Accept: text/html' "http://127.0.0.1:$port/sign-in" || true)"
      api_code="$(curl --max-time 3 -s -o /dev/null -w '%{http_code}' \
        -H "Host: $host" -H 'Accept: application/json' "http://127.0.0.1:$port/api/properties" || true)"
      if [[ "$sign_in_code" == 200 && "$api_code" == 401 ]]; then
        pid="$(sudo systemctl show "$unit" -p MainPID --value)"
        sleep 3
        restarts="$(sudo systemctl show "$unit" -p NRestarts --value)"
        [[ "$restarts" == 0 && "$pid" != 0 &&
          "$(sudo systemctl show "$unit" -p MainPID --value)" == "$pid" ]] ||
          die "Service restarted during readiness checks; inspect its journal."
        sudo systemctl is-active --quiet "$unit"
        return
      fi
    fi
    sleep 1
  done
  sudo journalctl -u "$unit" -n 25 --no-pager
  die "Readiness failed. Do not activate access."
}
activate_operator() {
  as_owner "$1" hosted-admin "$deployment" enrollments
  say "Verify the subject against the intended operator. Do not reuse A's subject for B."
  ask EPM_SUBJECT "Exact verified enrollment subject (not saved):"
  [[ "$EPM_SUBJECT" =~ ^[A-Za-z0-9_:@./-]+$ ]] || die "A verified subject is required."
  confirm "Activate this verified subject for instance $instance?" || die "Left fenced; activation cancelled."
  as_owner "$1" hosted-admin "$deployment" activate --subject "$EPM_SUBJECT"
  unset EPM_SUBJECT
  say "On your Mac, open $origin/sign-in."
  say "Renew Cloudflare sign-in, complete the assigned email sign-in, then Continue to workspace."
}
browser_acceptance() {
  say "On the Mac at $origin:"
  step "Check Home, Properties, Money and Settings against familiar existing records."
  step "Open/download an existing attachment; if none exists, record NOT TESTED."
  step "Make a harmless synthetic edit, refresh, check History, then restore the original value."
  step "Confirm the other instance remains usable and isolated."
  ask EPM_ACCEPTANCE "Evidence/notes, including any NOT TESTED checks (required):"
  [[ -n "$EPM_ACCEPTANCE" && "$EPM_ACCEPTANCE" != *$'\n'* ]] || die "Acceptance notes required."
  if ! confirm "Accept this instance, including the stated test limitations?"; then
    as_owner "$1" hosted-admin "$deployment" disable
    sudo systemctl stop "$unit"
    die "Not accepted; stopped and fenced. Use Rollback or investigate before resuming."
  fi
  printf '%s\n' "$EPM_ACCEPTANCE" | sudo tee "$record/browser-acceptance.txt" >/dev/null
}
archive_check() {
  # Validate paths/types before root extraction, including macOS metadata.
  "$previous_python" - "$archive" <<'PY'
import sys, tarfile
from pathlib import PurePosixPath
with tarfile.open(sys.argv[1], "r:gz") as archive:
    names = {}
    for member in archive.getmembers():
        path = PurePosixPath(member.name)
        if path.is_absolute() or ".." in path.parts or not (member.isfile() or member.isdir()):
            raise SystemExit("Unsafe archive entry; refusing extraction.")
        if any(p.startswith("._") or p in {".DS_Store", "__pycache__"} for p in path.parts):
            raise SystemExit("macOS metadata/cache in archive; rebuild on Mac.")
        if member.isfile():
            if str(path) in names or str(path) == ".":
                raise SystemExit("Duplicate archive entry.")
            names[str(path)] = member
    required = {"SHA256SUMS", "SOURCE_COMMIT.txt", "TEST_EVIDENCE.txt",
                "stage_schema_resources.py", "verify_installation.py", "release-vm.sh",
                "schema-resources/alembic.ini"}
    if not required <= names.keys() or len([n for n in names if n.endswith(".whl")]) != 1:
        raise SystemExit("Incomplete release bundle.")
    for name in names:
        if name.endswith(".py") and b"\0" in archive.extractfile(names[name]).read():
            raise SystemExit("Null bytes in Python source; rebuild on Mac.")
PY
}
install_release() {
  stage "Choose the release and verify its independent checksum"
  select_release
  select_instance
  say "The selected instance supplies Python/dependencies only; no service is stopped."
  current_python
  archive="$HOME/$EPM_RELEASE.tar.gz"
  [[ -f "$archive" && ! -L "$archive" ]] || die "Archive missing from administrator home."
  ask EPM_ARCHIVE_SHA256 "Paste archive SHA-256 from the Mac wizard (not the transferred file):"
  [[ "$EPM_ARCHIVE_SHA256" =~ ^[a-f0-9]{64}$ ]] || die "Expected 64 lowercase hexadecimal characters."
  local digest
  digest="$(sha256sum "$archive")"; digest="${digest%% *}"
  [[ "$digest" == "$EPM_ARCHIVE_SHA256" ]] || die "Archive checksum mismatch."
  [[ ! -e "$next" && ! -L "$next" ]] || die "Release already exists; use Deploy or a new ID."
  archive_check

  stage "Install a fresh release beside the running services"
  confirm "Install verified $EPM_RELEASE using the current hosted Python/dependency set?" || die "Installation cancelled."
  sudo mkdir -m 0755 "$next"
  sudo tar --no-same-owner -xzf "$archive" -C "$next"
  ( cd "$next"; sudo sha256sum --check SHA256SUMS )
  sudo chown -R root:root "$next"
  sudo chmod -R u=rwX,go=rX "$next"
  sudo "$previous_python" -m pip freeze --exclude easy-property-management |
    sudo tee "$next/constraints.txt" >/dev/null
  sudo chmod 0600 "$next/constraints.txt"
  sudo "$previous_python" -m venv "$next/venv"
  local wheels=( "$next"/*.whl )
  [[ "${#wheels[@]}" == 1 && -f "${wheels[0]}" ]] || die "Expected one wheel."
  # Constraints alone do not install hosted extras such as boto3.
  sudo "$next/venv/bin/python" -m pip install --requirement "$next/constraints.txt" \
    --constraint "$next/constraints.txt" "${wheels[0]}"

  stage "Verify installed resources"
  sudo "$next/venv/bin/python" -m pip check
  sudo "$next/venv/bin/python" "$next/stage_schema_resources.py" "$next/schema-resources"
  sudo "$next/venv/bin/python" "$next/verify_installation.py"
  cli_check "$next/venv/bin/python"
  sudo install -d -m 0700 "$next/wizard-state"
  printf '%s\n' "$EPM_ARCHIVE_SHA256" | sudo tee "$next/wizard-state/archive-sha256.txt" >/dev/null
  say "Installed, not deployed. Re-run this wizard and choose Deploy, A first."
}
deploy_release() {
  stage "Choose the installed release and instance"
  select_release
  select_instance
  [[ -x "$next/venv/bin/python" ]] || die "Install the release first."
  cli_check "$next/venv/bin/python"
  if [[ "$instance" == b ]]; then
    confirm "Has A passed browser acceptance and remained usable on this release?" || die "Accept A first."
  fi
  current_python
  [[ "$previous_python" != "$next/venv/bin/python" ]] || die "Already selected in systemd. Choose Resume; do not repeat backup/switch."
  read_origin

  stage "Record rollback and drain operator work"
  sudo install -d -m 0700 "$next/wizard-state"
  record="$(sudo mktemp -d "$next/wizard-state/$instance.XXXXXXXX")"
  write_env EPM_DEPLOY_RECORD "$record"
  printf '%s\n' "$previous_python" | sudo tee "$record/previous-python.txt" >/dev/null
  sudo systemctl show "$unit" -p ExecStart --value | sudo tee "$record/previous-execstart.txt" >/dev/null
  sudo test ! -L "$dropin" || die "Release drop-in is a symlink; inspect manually."
  if sudo test -f "$dropin"; then
    sudo cp -p "$dropin" "$record/90-release.conf.before"
  else
    sudo touch "$record/dropin-was-absent"
  fi
  say "Rollback record: $record"
  confirm "Has the operator saved/reconciled work? Disable $instance and stop its writer?" || die "Deployment cancelled."
  as_owner "$previous_python" hosted-admin "$deployment" disable
  sudo systemctl stop "$unit"
  ensure_stopped

  stage "Create and validate a pre-release encrypted backup"
  local output="/var/backups/$account/before-$EPM_RELEASE-$(date -u +%Y%m%dT%H%M%SZ).epm-backup"
  say "Backup: $output"
  say "Use the application's hidden passphrase prompt. The wizard never stores it."
  as_owner "$previous_python" hosted-backup "$deployment" --output "$output" \
    --staging-directory "/var/backups/$account/staging"
  printf '%s\n' "$output" | sudo tee "$record/backup-path.txt" >/dev/null

  stage "Validate the new release against existing records"
  ensure_stopped
  validate_instance "$next/venv/bin/python"

  stage "Generate and verify the instance-specific systemd override"
  sudo mkdir -p "$(dirname "$dropin")"
  printf '[Service]\nExecStart=\nExecStart=%s -m app --config %s serve-hosted --deployment %s --port %s\n' \
    "$next/venv/bin/python" "$local_config" "$deployment" "$port" |
    sudo tee "$record/90-release.conf.new" >/dev/null
  sudo cat "$record/90-release.conf.new"
  confirm "Switch only $unit to this exact command?" || die "Left stopped and fenced."
  sudo install -o root -g root -m 0644 "$record/90-release.conf.new" "$dropin"
  sudo systemctl daemon-reload
  sudo systemd-analyze verify "$unit"
  check_exec "$(sudo systemctl show "$unit" -p ExecStart --value)" "$next/venv/bin/python"
  sudo systemctl reset-failed "$unit"
  sudo systemctl start "$unit"
  readiness

  stage "Reactivate the intended operator"
  activate_operator "$next/venv/bin/python"

  stage "Browser acceptance on the Mac"
  browser_acceptance "$next/venv/bin/python"

  stage "Record completion"
  sudo systemctl show "$unit" -p ExecStart -p MainPID -p NRestarts |
    sudo tee "$record/accepted-service.txt" >/dev/null
  say "Accepted instance $instance. Record this operation in CLOUDFLARE_OPERATIONS.md."
  say "Private evidence/rollback record: $record"
  say "Retain the old release and backup. Publish the verified backup off-host using the recovery runbook."
  [[ "$instance" != a ]] || say "Re-run and choose Deploy B after confirming A stays usable."
}
select_record() {
  sudo find "$next/wizard-state" -maxdepth 1 -type d -name "$instance.*" -print
  ask EPM_DEPLOY_RECORD "Exact deployment/rollback directory printed above:"
  [[ "$EPM_DEPLOY_RECORD" == "$next/wizard-state/$instance."* &&
    "$EPM_DEPLOY_RECORD" =~ ^/opt/epm/releases/release-[0-9]{8}-[0-9]{2,}/wizard-state/[ab]\.[A-Za-z0-9]+$ ]] ||
    die "Invalid deployment record path."
  record="$EPM_DEPLOY_RECORD"
}
resume_release() {
  stage "Choose the interrupted deployment"
  select_release
  select_instance
  select_record
  sudo test -s "$record/backup-path.txt" || die "No successful backup recorded; inspect manually."
  check_exec "$(sudo systemctl show "$unit" -p ExecStart --value)" "$next/venv/bin/python"
  read_origin

  stage "Verify or restart the selected release"
  if ! sudo systemctl is-active --quiet "$unit"; then
    ensure_stopped
    validate_instance "$next/venv/bin/python"
    confirm "Start this already-selected release?" || die "Left stopped."
    sudo systemctl start "$unit"
  fi
  readiness

  stage "Reactivate and complete browser acceptance"
  activate_operator "$next/venv/bin/python"
  browser_acceptance "$next/venv/bin/python"
  say "Resumed and accepted. Record the result and retain backup/rollback evidence: $record"
}
rollback_release() {
  stage "Select the failed release and its saved rollback record"
  select_release
  select_instance
  select_record
  previous_python="$(sudo cat "$record/previous-python.txt")"
  [[ "$previous_python" =~ ^/opt/epm/releases/[A-Za-z0-9][A-Za-z0-9._-]*/venv/bin/python$ ]] ||
    die "Invalid previous interpreter in record."
  cli_check "$previous_python"
  read_origin
  say "Previous interpreter: $previous_python"
  confirm "Has operator work been saved/reconciled? Fence and stop this instance for rollback?" || die "Rollback cancelled."
  as_owner "$next/venv/bin/python" hosted-admin "$deployment" disable
  sudo systemctl stop "$unit"
  ensure_stopped

  stage "Check old-release compatibility before switching"
  validate_instance "$previous_python"
  say "If validation fails, restore a compatible backup into a separate destination; never modify SQLite."
  confirm "Restore only the saved release drop-in?" || die "Left stopped and fenced."
  sudo test ! -L "$dropin" || die "Drop-in is a symlink; inspect manually."
  if sudo test -f "$record/90-release.conf.before"; then
    sudo install -o root -g root -m 0644 "$record/90-release.conf.before" "$dropin"
  elif sudo test -f "$record/dropin-was-absent"; then
    # Remove only the wizard's own override, never other instance drop-ins.
    sudo cmp "$dropin" "$record/90-release.conf.new"
    sudo rm -- "$dropin"
  else
    die "No saved drop-in state. Inspect manually."
  fi
  sudo systemctl daemon-reload
  sudo systemd-analyze verify "$unit"
  check_exec "$(sudo systemctl show "$unit" -p ExecStart --value)" "$previous_python"
  sudo systemctl start "$unit"
  readiness

  stage "Reactivate and accept the rolled-back instance"
  activate_operator "$previous_python"
  browser_acceptance "$previous_python"
  say "Record rollback and its checks; preserve failed release evidence and backups."
}
inspect_host() {
  stage "Services and bounded workspace mounts"
  sudo systemctl status epm-hosted@a.service epm-hosted@b.service epm-cloudflared.service --no-pager || true
  sudo systemctl show epm-hosted@a.service epm-hosted@b.service -p ExecStart -p MainPID -p NRestarts
  sudo findmnt --mountpoint /var/lib/epm-a/volume
  sudo findmnt --mountpoint /var/lib/epm-b/volume
  df -h / /var/lib/epm-a/volume /var/lib/epm-b/volume
  free -h
  pause "Review the status before viewing recent logs."
  stage "Recent application logs"
  sudo journalctl -u epm-hosted@a.service -u epm-hosted@b.service --since '1 hour ago' --no-pager
  say "No services, enrollment, configuration or workspace records were changed."
}
main() {
  if [[ "${1:-}" == --help ]]; then
    printf 'Usage: bash epm-release-vm.sh\nInteractive menu: inspect, install, deploy, resume, or explicit rollback.\n'
    return
  fi
  [[ $# == 0 && "$(uname -s)" == Linux ]] || die "Run on the Linux VM; use --help for usage."
  [[ -t 0 && -t 1 ]] || die "Run interactively in a terminal."
  [[ "$EUID" != 0 ]] || die "Run as the administrator login user, not sudo bash."
  for tool in sudo systemctl systemd-analyze sha256sum curl tar; do need "$tool"; done
  unset PYTHONPATH PYTHONHOME
  umask 022
  mkdir -p "$HOME/.local/state/epm-release-wizard"
  ENV_FILE="$HOME/.local/state/epm-release-wizard/vm.env"
  touch "$ENV_FILE"
  chmod 600 "$ENV_FILE"
  say "Choose: inspect, install, deploy, resume, rollback. Installation never switches services."
  ask EPM_ACTION "Action:"
  case "$EPM_ACTION" in
    inspect) TOTAL_STAGES=2 ;;
    install) TOTAL_STAGES=3 ;;
    deploy) TOTAL_STAGES=8 ;;
    resume) TOTAL_STAGES=3 ;;
    rollback) TOTAL_STAGES=3 ;;
    *) die "Unknown action." ;;
  esac
  sudo -v
  trap 'failed "$?"' ERR
  trap 'die "Interrupted. No automatic rollback or reactivation; inspect current state."' INT TERM
  banner "EPM · VM $EPM_ACTION wizard"
  local next instance port unit account local_config deployment dropin previous_python archive origin host record
  case "$EPM_ACTION" in
    inspect) inspect_host ;;
    install) install_release ;;
    deploy) deploy_release ;;
    resume) resume_release ;;
    rollback) rollback_release ;;
  esac
  finish
}

main "$@"

